const H = { Accept: 'application/json', 'Content-Type': 'application/json' };

const login = await this.helpers.httpRequest({ method: 'POST', url: B + '/api/auth/login', headers: H, json: true,
  body: { email: cfg.G54_MASTER_EMAIL, password: cfg.G54_MASTER_PASSWORD } });
const auth = { ...H, Authorization: 'Bearer ' + login.access_token };
await this.helpers.httpRequest({ method: 'POST', url: B + '/api/auth/switch-company', headers: auth, json: true, body: { company_id: cid } });
const postsResp = await this.helpers.httpRequest({ method: 'GET', url: B + '/api/rrss/posts', headers: auth, json: true });
const posts = (postsResp && postsResp.data) || postsResp || [];
const porMetaId = {};
for (const p of posts) if (p.post_id_platform) porMetaId[String(p.post_id_platform)] = p.id;

const rows = [], sinVincular = [];
const base = { period_start: m.period_start, period_end: m.period_end, leads: 0 };
for (const d of ((m.fb && m.fb.detalle) || [])) {
  const id = porMetaId[d.meta_id];
  if (!id) { sinVincular.push('facebook:' + d.meta_id); continue; }
  rows.push({ ...base, platform: 'facebook', social_post_id: id, alcance: d.alcance, impresiones: d.visualizaciones,
    engagement_count: (d.reacciones || 0) + (d.comentarios || 0) + (d.compartidos || 0) + (d.clics || 0),
    engagement_rate: d.alcance > 0 ? +(((d.reacciones || 0) + (d.comentarios || 0) + (d.compartidos || 0) + (d.clics || 0)) / d.alcance * 100).toFixed(2) : 0,
    clics: d.clics || 0, compartidos: d.compartidos || 0 });
}
for (const d of ((m.ig && m.ig.detalle) || [])) {
  const id = porMetaId[d.meta_id];
  if (!id) { sinVincular.push('instagram:' + d.meta_id); continue; }
  rows.push({ ...base, platform: 'instagram', social_post_id: id, alcance: d.alcance, impresiones: d.visualizaciones,
    engagement_count: d.interacciones || 0, engagement_rate: d.alcance > 0 ? +((d.interacciones || 0) / d.alcance * 100).toFixed(2) : 0,
    guardados: d.guardados || 0, compartidos: d.compartidos || 0 });
}
let guardado = null;
if (rows.length) {
  guardado = await this.helpers.httpRequest({ method: 'POST', url: B + '/api/agent/rrss/metricas', json: true,
    headers: { ...H, Authorization: 'Bearer ' + cfg.G54_AGENT_TOKEN }, body: { company_id: cid, metricas: rows } });
}
