const BASE = "https://apigrowth.mdarthurdigital.com";
const AGENT_TOKEN = "<G54_AGENT_TOKEN — ver .secrets.local.md>";

// Excluidas del despacho automático: empresas cuyas credenciales de Meta
// están confirmadas como copiadas/compartidas con otra empresa (no son
// datos reales propios) — hoy Orison (id 6) comparte el mismo page_id de
// Facebook que Crating Express (ver CLAUDE.md, hallazgo del 13-jul, decisión
// explícita del 07-sep de excluirla hasta que tenga sus propias redes).
const EXCLUIDAS = [6];

const empresasResp = await this.helpers.httpRequest({
  method: "GET",
  url: BASE + "/api/n8n/companies?activas=1&con_redes=1",
  headers: { Authorization: "Bearer " + AGENT_TOKEN, Accept: "application/json" },
  json: true,
});
const empresas = (empresasResp && empresasResp.data) || [];

const salida = [];
for (const emp of empresas) {
  if (EXCLUIDAS.includes(emp.id)) continue;

  let targets = [];
  try {
    const tResp = await this.helpers.httpRequest({
      method: "GET",
      url: BASE + "/api/agent/companies/" + emp.id + "/social-targets",
      headers: { Authorization: "Bearer " + AGENT_TOKEN, Accept: "application/json" },
      json: true,
    });
    targets = (tResp && tResp.data) || [];
  } catch (e) {
    continue; // empresa sin conexión resuelta - se salta, no se inventa nada
  }

  const fb = targets.find(t => t.platform === "Facebook" && t.listo);
  const ig = targets.find(t => t.platform === "Instagram" && t.listo);

  if (!fb && !ig) continue; // ninguna red lista - nada real que reportar

  salida.push({
    json: {
      company_id: emp.id,
      fb_page_id: fb ? fb.page_id : null,
      ig_user_id: ig ? ig.instagram_account_id : null,
    },
  });
}

return salida;

// Agregado 28-sep: métricas por post de la semana, vinculadas al post de G54 por
// post_id_platform (el id que devuelve Meta al publicar). Alimenta "Top Posts" del panel y
// la retroalimentación de Ideas AI (qué temas rindieron). G54 excluye del total de cuenta
// las filas con social_post_id, así que esto no duplica los números del panel.
// Requiere sesión: ninguna ruta con AGENT_TOKEN devuelve los posts publicados con su id de Meta.
const cfg = $('⚙️ Config Growth54').item.json;
const m = $('📊 Preparar Métricas G54').item.json;
const B = cfg.G54_BASE_URL;
const cid = parseInt(cfg.G54_COMPANY_ID, 10) || 1;
const H = { Accept: 'application/json', 'Content-Type': 'application/json' };

const login = await this.helpers.httpRequest({ method: 'POST', url: B + '/api/auth/login', headers: H, json: true,
  body: { email: cfg.G54_MASTER_EMAIL, password: cfg.G54_MASTER_PASSWORD } });
const auth = { ...H, Authorization: 'Bearer ' + login.access_token };
await this.helpers.httpRequest({ method: 'POST', url: B + '/api/auth/switch-company', headers: auth, json: true, body: { company_id: cid } });
const postsResp = await this.helpers.httpRequest({ method: 'GET', url: B + '/api/rrss/posts', headers: auth, json: true });
const posts = (postsResp && postsResp.data) || postsResp || [];
const porMetaId = {};
for (const p of posts) if (p.post_id_platform) porMetaId[String(p.post_id_platform)] = p.id;

const rows = [], sinVincular = [];
const base = { period_start: m.period_start, period_end: m.period_end, leads: 0 };
for (const d of ((m.fb && m.fb.detalle) || [])) {
  const id = porMetaId[d.meta_id];
  if (!id) { sinVincular.push('facebook:' + d.meta_id); continue; }
  rows.push({ ...base, platform: 'facebook', social_post_id: id, alcance: d.alcance, impresiones: d.visualizaciones,
    engagement_count: (d.reacciones || 0) + (d.comentarios || 0) + (d.compartidos || 0) + (d.clics || 0),
    engagement_rate: d.alcance > 0 ? +(((d.reacciones || 0) + (d.comentarios || 0) + (d.compartidos || 0) + (d.clics || 0)) / d.alcance * 100).toFixed(2) : 0,
    clics: d.clics || 0, compartidos: d.compartidos || 0 });
}
for (const d of ((m.ig && m.ig.detalle) || [])) {
  const id = porMetaId[d.meta_id];
  if (!id) { sinVincular.push('instagram:' + d.meta_id); continue; }
  rows.push({ ...base, platform: 'instagram', social_post_id: id, alcance: d.alcance, impresiones: d.visualizaciones,
    engagement_count: d.interacciones || 0, engagement_rate: d.alcance > 0 ? +((d.interacciones || 0) / d.alcance * 100).toFixed(2) : 0,
    guardados: d.guardados || 0, compartidos: d.compartidos || 0 });
}
let guardado = null;
if (rows.length) {
  guardado = await this.helpers.httpRequest({ method: 'POST', url: B + '/api/agent/rrss/metricas', json: true,
    headers: { ...H, Authorization: 'Bearer ' + cfg.G54_AGENT_TOKEN }, body: { company_id: cid, metricas: rows } });
}
return [{ json: { vinculados: rows.length, sin_vincular: sinVincular, guardado } }];
